[
	{
		"name": "",
		"text": "'You are bold, to approach me here. I have need of agents to execture a vendetta. Serve me, and you will be generously rewarded'",
		"options":
			[
				{
					"name": "The dragons are dead.",
                    "text": "'Excellent. Strixhaven's demise is assured!'",
					"action": [ { "deleteMapObject": -1 },
                    {"grantRewards": [
		      {"type": "item", "count": 1, "itemName": "Graduation Cap"},
                        {"type": "shards", "count": 50},
                        {"type": "card", "count": 1, "cardName": "Extus, Oriq Overlord"}            
                      ] } ]
                    ,
					"condition": [{"item": "Explorer's Cloak"}, {"item": "Librarian's Robes"}, {"item": "Oracle's Robes"}, {"item": "Witch's Cloak"}, {"item": "Student's Robes"}],
					"options": [ { "name": "(Continue)" } ]
				},
				{
					"name": "Who do you need dead?",
					"text": "'Straight to the point. Excellent. Kill the five founder dragons of the Strixhaven colleges. One resides in each biome. Show me the items they carried and receive your reward.'",
					"options": [ { "name": "You mentioned a reward?",
					"text": "'I have a unique item taken from a fallen Strixhaven dean, and a great many mana shards to offer.'",
					"options": [ { "name": "I'll consider it." } ]
					 }]
				},
                {
					"name": "No thanks, creep.",
					"text": "'Stay out of my way.'",
					"options": [ { "name": "(Continue)" } ]
				}
			]
	}
]

[
{
   "text": "The metallic scent of freshly spilled blood is thick in this chamber. Unholy mana swirls about, centering on a masked figure at the back of the room. Perhaps strangely, they don't appear to be hostile.",
   "options": [{
